-- Crownlight Classroom Design Registry V1 | 2026-11-01
-- No existing member progress, plans, lessons, wallets, grading or Stripe rows are modified.
BEGIN;
CREATE TABLE IF NOT EXISTS public.cl_classroom_presets (
 preset_code text PRIMARY KEY CHECK (preset_code ~ '^[a-z0-9-]{3,48}$'),
 label text NOT NULL CHECK (char_length(label) BETWEEN 3 AND 100),
 config jsonb NOT NULL CHECK (jsonb_typeof(config)='object' AND octet_length(config::text)<=4096),
 active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.cl_classroom_membership_codes (
 plan_code text PRIMARY KEY CHECK (plan_code ~ '^[A-Z0-9_]{3,48}$'),
 display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 3 AND 120),
 default_preset_code text NOT NULL REFERENCES public.cl_classroom_presets(preset_code),
 active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.cl_classroom_layouts (
 plan_code text NOT NULL REFERENCES public.cl_classroom_membership_codes(plan_code),
 channel text NOT NULL CHECK (channel IN ('draft','published')),
 version integer NOT NULL DEFAULT 1 CHECK (version BETWEEN 1 AND 2147483646),
 preset_code text NOT NULL REFERENCES public.cl_classroom_presets(preset_code),
 config jsonb NOT NULL CHECK (jsonb_typeof(config)='object' AND octet_length(config::text)<=4096),
 editor_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
 updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY (plan_code,channel)
);
CREATE TABLE IF NOT EXISTS public.cl_classroom_layout_history (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 plan_code text NOT NULL,
 channel text NOT NULL,
 version integer NOT NULL,
 preset_code text NOT NULL,
 config jsonb NOT NULL,
 actor_user_id uuid,
 recorded_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE (plan_code,channel,version)
);
CREATE OR REPLACE FUNCTION public.cl_classroom_record_layout_revision_v1()
 RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.version<>OLD.version+1 THEN
   RAISE EXCEPTION 'Classroom layout version must increase by exactly one';
 END IF;
 INSERT INTO public.cl_classroom_layout_history(plan_code,channel,version,preset_code,config,actor_user_id)
 VALUES(NEW.plan_code,NEW.channel,NEW.version,NEW.preset_code,NEW.config,NEW.editor_user_id);
 RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.cl_classroom_record_layout_revision_v1() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS cl_classroom_revision_capture_v1 ON public.cl_classroom_layouts;
CREATE TRIGGER cl_classroom_revision_capture_v1 AFTER INSERT OR UPDATE
 ON public.cl_classroom_layouts FOR EACH ROW EXECUTE FUNCTION public.cl_classroom_record_layout_revision_v1();
ALTER TABLE public.cl_classroom_presets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cl_classroom_membership_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cl_classroom_layouts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cl_classroom_layout_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cl_classroom_presets,public.cl_classroom_membership_codes,
 public.cl_classroom_layouts,public.cl_classroom_layout_history FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.cl_classroom_presets,public.cl_classroom_membership_codes,public.cl_classroom_layouts,public.cl_classroom_layout_history TO service_role;
GRANT INSERT,UPDATE ON public.cl_classroom_layouts TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.cl_classroom_layout_history_id_seq TO service_role;
