INSERT INTO public.cl_classroom_layouts(plan_code,channel,version,preset_code,config)
SELECT m.plan_code,'draft',1,p.preset_code,p.config
FROM public.cl_classroom_membership_codes m JOIN public.cl_classroom_presets p ON p.preset_code=m.default_preset_code
WHERE m.plan_code IN ('FREE','FOUNDING_14','FOUNDING_30','FOUNDING_60','FULL_MONTHLY','FULL_ANNUAL','LIFETIME','ONDEMAND_MONTHLY')
ON CONFLICT (plan_code,channel) DO NOTHING;
COMMIT;
